import type { Metadata } from "next";
import { Suspense } from "react";
import { VersionSwitcher } from "@/components/version-switcher";
import { getProduct } from "@/lib/products";
import { getSnapshots, getVersions } from "@/lib/snapshots";

// The page around a frozen version of a product (its route is generated by
// scripts/snapshot.mjs): the version itself, full screen, plus the switcher.
// Like the live product's page, it renders inside a Suspense boundary so the
// app can read the clock while it prerenders.
export function SnapshotPage({ slug, id, children }: { slug: string; id: string; children: React.ReactNode }) {
  return (
    <Suspense>
      {children}
      <Switcher slug={slug} id={id} />
    </Suspense>
  );
}

async function Switcher({ slug, id }: { slug: string; id: string }) {
  const { metadata } = await getProduct(slug);
  return <VersionSwitcher slug={slug} versions={getVersions(slug)} current={id} placement={metadata.versionBar} />;
}

export function snapshotMetadata(slug: string, id: string): Metadata {
  const snapshot = getSnapshots(slug).find((s) => s.id === id);
  return { title: snapshot?.name ?? id };
}
